import * as THREE from 'three/webgpu';
import { texture, uv, vec2, mix, float } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-1-label';

  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(width, height);

  const uvNode = uv();
  const texNode = texture(map, uvNode);
  const gradientNode = mix(
    vec2(0.086, 0.086).x,
    vec2(0.024, 0.024).x,
    uvNode.y
  );
  const inkColor = float(0.086);
  const finalColor = mix(texNode, texNode.mul(1.0), 1.0);

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = finalColor;
  material.transparent = false;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'card-label-plane';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh(ctx.fontAtlas, {
      text: 'Collection 2',
      font: 'display',
      weight: 400,
      sizeEm: 0.34,
      color: '#e8ecf2',
      align: 'center',
      atlas: 0,
      rect: { x: 0, y: 0, w: 512, h: 320 },
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  } catch (e) {
    textMesh = null;
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
      group.remove(textMesh);
    }
    group.remove(plane);
  };

  return group;
}
